--
-- Name: auto_assign_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_assign_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_location_id BIGINT;
            BEGIN
                SELECT id INTO v_location_id
                FROM locations
                WHERE ST_Contains(geom, NEW.geom)
                ORDER BY CASE
                    WHEN level = 'neighborhood' THEN 1
                    WHEN level = 'city' THEN 2
                    WHEN level = 'province' THEN 3
                    ELSE 4
                END
                LIMIT 1;

                IF v_location_id IS NOT NULL THEN
                    NEW.location_id := v_location_id;
                END IF;

                RETURN NEW;
            END;
            $$;


--
-- Name: check_is_leaf_category(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_is_leaf_category() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                IF EXISTS (
                    SELECT 1
                    FROM incident_categories
                    WHERE parent_id = NEW.incident_category_id
                ) THEN
                    RAISE EXCEPTION 'Cannot associate an incident with a parent category (must be a leaf category). ID: %', NEW.incident_category_id;
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: log_incident_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_incident_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_actor_id BIGINT;
            BEGIN
                IF OLD.status IS DISTINCT FROM NEW.status THEN
                    v_actor_id := NULLIF(current_setting('app.current_user_id', true), '')::BIGINT;

                    IF v_actor_id IS NULL THEN
                        v_actor_id := COALESCE(NEW.user_id, OLD.user_id);
                    END IF;

                    VALUES (
                        NEW.id,
                        v_actor_id,
                        OLD.status,
                        NEW.status,
                        NOW()
                    );
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: notify_on_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                IF OLD.status IS DISTINCT FROM NEW.status THEN
                    SELECT
                        COALESCE(assignments.user_id, NEW.user_id),
                        NEW.id,
                        'status_change',
                        'El estado de la incidencia #' || NEW.id || ' ha cambiado a ' || NEW.status,
                        false,
                        NOW()
                    FROM assignments
                    WHERE incident_id = NEW.id
                    ON CONFLICT DO NOTHING;
                END IF;
                RETURN NEW;
            END;
            $$;


